(()=>{
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let motion=!reduced.matches;const toggle=document.getElementById('motion-toggle');const canvas=document.getElementById('matrix'),ctx=canvas.getContext('2d');let columns=[],w=0,h=0,last=0,visible=true;
function resize(){w=canvas.clientWidth;h=canvas.clientHeight;canvas.width=w;canvas.height=h;columns=Array.from({length:Math.ceil(w/24)},()=>Math.random()*-80)}resize();window.addEventListener('resize',resize);
function state(){document.body.classList.toggle('effects-off',!motion);toggle.textContent=motion?'Effects on ◈':'Effects off ◇';toggle.setAttribute('aria-pressed',String(motion));if(!motion){document.querySelectorAll('.service,.offer-card').forEach(el=>el.style.transform='');ctx.clearRect(0,0,w,h)}}toggle.addEventListener('click',()=>{motion=!motion;state()});reduced.addEventListener('change',()=>{motion=!reduced.matches;state()});state();
new IntersectionObserver(entries=>{visible=entries[0].isIntersecting}).observe(canvas);
function rain(t){requestAnimationFrame(rain);if(!motion||!visible||document.hidden||t-last<85)return;last=t;ctx.fillStyle='rgba(9,20,32,.12)';ctx.fillRect(0,0,w,h);ctx.font='12px monospace';columns.forEach((y,i)=>{ctx.fillStyle=i%4===0?'#d9b56b':'#5a97a8';ctx.fillText('0101GW240'[Math.floor(Math.random()*9)],i*24,y*20);if(y*20>h&&Math.random()>.98)columns[i]=-Math.random()*20;else columns[i]+=.5})}requestAnimationFrame(rain);
const compare=document.querySelector('.compare'),slider=document.getElementById('transformation-slider');let playFrame=0;
function setSplit(value){slider.value=value;compare.style.setProperty('--split',value+'%');slider.setAttribute('aria-valuetext',Math.round(value)+' percent repaired view')}
slider.addEventListener('input',()=>{cancelAnimationFrame(playFrame);setSplit(slider.value)});document.getElementById('transform-play').addEventListener('click',()=>{cancelAnimationFrame(playFrame);if(!motion){setSplit(Number(slider.value)>50?0:100);return}const start=performance.now();function animate(t){const p=Math.min((t-start)/2000,1);setSplit((.5-Math.cos(p*Math.PI)/2)*100);if(p<1)playFrame=requestAnimationFrame(animate)}playFrame=requestAnimationFrame(animate)});
if(matchMedia('(hover:hover) and (pointer:fine)').matches)document.querySelectorAll('.service,.offer-card').forEach(el=>{el.addEventListener('pointermove',e=>{if(!motion)return;const r=el.getBoundingClientRect();el.style.transform=`perspective(900px) rotateX(${-(e.clientY-r.top-r.height/2)/r.height*4}deg) rotateY(${(e.clientX-r.left-r.width/2)/r.width*4}deg)`});el.addEventListener('pointerleave',()=>el.style.transform='')});
const dialog=document.getElementById('brochure-dialog'),brochureImg=document.getElementById('brochure-image');document.querySelectorAll('.brochure-open').forEach(button=>button.addEventListener('click',()=>{document.getElementById('brochure-title').textContent=button.dataset.title;brochureImg.src=button.dataset.brochure;brochureImg.alt=button.dataset.title;document.getElementById('brochure-download').href=button.dataset.brochure;dialog.showModal()}));document.getElementById('brochure-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_service_enquiry',description:'Select a vehicle concern and prepare the visible WhatsApp enquiry without sending it.',inputSchema:{type:'object',properties:{concern:{type:'string',enum:Object.keys(advice)}},required:['concern'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Object.hasOwn(advice,input.concern))throw Error('Select a valid vehicle concern.');concern.value=input.concern;update();return {title:document.getElementById('recommend-title').textContent,whatsappUrl:document.getElementById('enquire').href}}})).catch(()=>{})}catch{}}
})();
